from playwright.sync_api import sync_playwright
from pathlib import Path
p=Path(__file__).resolve().parents[1]
html=(p/'index.html').read_text().replace('<link rel="stylesheet" href="./styles.css">', '<style>'+(p/'styles.css').read_text()+'</style>').replace('<script src="./app.js" defer></script>','<script>'+(p/'app.js').read_text()+'</script>')
with sync_playwright() as pp:
 b=pp.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 context=b.new_context(accept_downloads=True,viewport={'width':1360,'height':850})
 x=context.new_page();errors=[];x.on('pageerror',lambda e:errors.append(str(e)))
 x.set_content(html,wait_until='load');x.wait_for_timeout(450)
 print('title',x.locator('h1').first.inner_text());print('nav',x.locator('.navlink').count())
 x.screenshot(path=str(p/'tests/desktop_v2.png'),full_page=True)
 x.locator('a[href="#/stakeholders"]').click();x.wait_for_timeout(120)
 print('actor count',x.locator('.clickrow').count())
 print('scroll',x.locator('.profile-scroll').evaluate('(e)=>({scrollHeight:e.scrollHeight,clientHeight:e.clientHeight,overflow:getComputedStyle(e).overflowY})'))
 x.locator('button[data-act="select-actor"]').nth(2).click();print('actor selected',x.locator('.profile-scroll h2').inner_text())
 x.locator('a[href="#/issues"]').click();x.locator('button[data-act="example"]').first.click();x.wait_for_timeout(150)
 print('workbench',x.locator('h1').first.inner_text())
 x.locator('[name="owner"]').fill('Proposed only, requires review');x.locator('#caseForm button[type="submit"]').click()
 x.locator('[data-gate="law"][data-part="state"]').select_option('documented')
 x.locator('[data-gate="law"][data-part="url"]').fill('https://www.un.org/en/about-us/un-charter/full-text')
 x.locator('[data-gate="law"][data-part="note"]').fill('Public Charter Articles 2, 51; independent legal review required.')
 x.locator('[data-act="review"]').first.click();print('assessment',x.locator('.decision h3').first.inner_text())
 x.locator('a[href="#/verification"]').first.click();x.locator('[name="scope"]').fill('Civilian energy infrastructure only');x.locator('#protocolForm button[type="submit"]').click()
 x.locator('a[href="#/decisions"]').click();x.locator('#entryForm [name="text"]').fill('Both governments must accept specific definition');x.locator('#entryForm button[type="submit"]').click();print('ledger entry exists',x.get_by_text('Both governments must accept specific definition').count())
 x.locator('a[href="#/evidence"]').click();x.locator('h1').filter(has_text='Source register').wait_for(timeout=3000);print('source card count',x.locator('article.card').count());x.locator('[name="name"]').fill('Test source');x.locator('[name="date"]').fill('2026-10-16');x.locator('[name="url"]').fill('https://example.org/test');x.locator('[name="claim"]').fill('Test assertion, not verified');x.locator('#sourceForm button').click();print('user source',x.get_by_text('Test source').count())
 x.locator('a[href="#/settings"]').click();x.locator('h1').filter(has_text='Workspace').wait_for(timeout=3000);print('settings',x.locator('h1').inner_text())
 with x.expect_download() as dl:x.locator('[data-act="export-backup"]').click()
 data=dl.value;print('download name',data.suggested_filename)
 x.locator('#themeSelect').select_option('dark');print('theme',x.evaluate('document.documentElement.dataset.theme'))
 print('JS ERRORS:',errors)
 mob=b.new_context(viewport={'width':390,'height':844});m=mob.new_page();m.set_content(html);m.wait_for_timeout(450);m.screenshot(path=str(p/'tests/mobile_v2.png'),full_page=True)
 print('mobile horizontal overflow',m.evaluate('document.documentElement.scrollWidth>window.innerWidth'))
 m.locator('#menuToggle').click();print('mobile nav',m.locator('#menuToggle').get_attribute('aria-expanded'));m.keyboard.press('Escape');print('mobile closed',m.locator('#menuToggle').get_attribute('aria-expanded'))
 b.close()
